function Feature({ icon: Icon, title, detail }: { icon: typeof Link2; title: string; detail: string }) { return <div className="flex gap-4"><div className="mt-0.5 rounded-lg bg-accent/40 p-2.5 text-primary"><Icon className="h-4 w-4" /></div><div><h3 className="font-bold text-primary">{title}</h3><p className="mt-1 text-sm leading-6 text-muted-foreground">{detail}</p></div></div>; }
function Brand({ light = false, small = false }: { light?: boolean; small?: boolean }) { return <Link data-testid="link-brand" href="/" className={cx('flex items-center gap-2.5', light ? 'text-primary-foreground' : 'text-primary')}><span className={cx('grid place-items-center rounded-md bg-accent text-primary font-bold', small ? 'h-6 w-6 text-[10px]' : 'h-8 w-8 text-sm')}>A</span><span className={cx('font-bold tracking-[-.04em]', small ? 'text-sm' : 'text-base')}>Amrita <span className="font-normal opacity-60">Connect</span></span></Link>; }

function AuthLayout({ children, title, detail, mode }: { children: React.ReactNode; title: string; detail: string; mode: 'login' | 'register' }) {
  return <div className="grain grid min-h-[100dvh] bg-background lg:grid-cols-[.8fr_1.2fr]"><div className="hidden bg-primary p-10 text-primary-foreground lg:flex lg:flex-col lg:justify-between"><Brand light /><div><div className="mono mb-5 text-[10px] uppercase tracking-[.22em] text-primary-foreground/45">A network with roots</div><p className="max-w-md text-5xl font-bold leading-[1.04] tracking-[-.06em]">The right people are closer than you think.</p><p className="mt-6 max-w-sm text-sm leading-7 text-primary-foreground/60">One trusted place to find mentors, collaborators, opportunities, and the wider Amrita community.</p></div><div className="flex items-center gap-3 text-xs text-primary-foreground/45"><span className="h-2 w-2 rounded-full bg-accent" /> Amrita Connect <span className="ml-auto">01 / 24</span></div></div><div className="flex flex-col px-5 py-6 sm:px-12 lg:px-24 lg:py-10"><div className="flex items-center justify-between lg:justify-end"><div className="lg:hidden"><Brand /></div><Link data-testid={`link-auth-${mode === 'login' ? 'register' : 'login'}`} href={mode === 'login' ? '/register' : '/login'} className="text-sm font-semibold text-muted-foreground hover:text-primary">{mode === 'login' ? 'Create account' : 'Sign in instead'} <ChevronRight className="inline h-3 w-3" /></Link></div><div className="my-auto w-full max-w-md py-12"><div className="mono mb-3 text-[10px] font-bold uppercase tracking-[.2em] text-muted-foreground">{mode === 'login' ? 'Welcome back' : 'Join the community'}</div><h1 className="text-4xl font-bold tracking-[-.06em] text-primary">{title}</h1><p className="mt-3 text-sm leading-6 text-muted-foreground">{detail}</p>{children}</div><p className="text-xs text-muted-foreground">By continuing, you agree to keep Amrita Connect a trusted academic space.</p></div></div>;
}
function LoginPage() {
  const login = useLogin(); const [, setLocation] = useLocation(); const [email, setEmail] = useState(''); const [password, setPassword] = useState(''); const [error, setError] = useState('');
  const submit = (e: React.FormEvent) => { e.preventDefault(); setError(''); login.mutate({ data: { email, password } }, { onSuccess: (data) => { setAuthSession(data.token); queryClient.invalidateQueries({ queryKey: getGetCurrentUserQueryKey() }); setLocation('/dashboard'); }, onError: () => setError('Those details did not work. Check your email and password, then try again.') }); };
  return <AuthLayout mode="login" title="Good to see you." detail="Sign in to pick up where you left off."><form onSubmit={submit} className="mt-8 space-y-5"><Field id="email" label="University or personal email" type="email" value={email} onChange={(e) => setEmail(e.target.value)} required /><Field id="password" label="Password" type="password" value={password} onChange={(e) => setPassword(e.target.value)} required /><div className="flex justify-end"><button data-testid="button-forgot-password" type="button" className="text-xs font-semibold text-muted-foreground hover:text-primary" onClick={() => setError('Please contact your campus administrator to reset your password.')}>Forgot password?</button></div>{error && <p data-testid="status-auth-error" className="rounded-lg bg-destructive/10 p-3 text-sm text-destructive">{error}</p>}<Button data-testid="button-submit-login" type="submit" className="w-full py-3.5" disabled={login.isPending}>{login.isPending ? <LoaderCircle className="h-4 w-4 animate-spin" /> : <LogIn className="h-4 w-4" />}Sign in</Button></form></AuthLayout>;
}
function RegisterPage() {
  const register = useRegister(); const [, setLocation] = useLocation(); const [form, setForm] = useState({ fullName: '', email: '', password: '', role: 'student' as 'student' | 'alumni' | 'faculty' | 'researcher', campus: campuses[0], department: departments[0], graduationYear: '' }); const [error, setError] = useState('');
  const update = (key: string, value: string) => setForm((prev) => ({ ...prev, [key]: value }));
  const submit = (e: React.FormEvent) => { e.preventDefault(); setError(''); register.mutate({ data: { ...form, graduationYear: form.graduationYear ? Number(form.graduationYear) : null } }, { onSuccess: (data) => { setAuthSession(data.token); queryClient.invalidateQueries({ queryKey: getGetCurrentUserQueryKey() }); setLocation('/dashboard'); }, onError: () => setError('We could not create your account. Please review the details and try again.') }); };
  return <AuthLayout mode="register" title="Make your place." detail="Create a profile that helps the right people understand what you are building toward."><form onSubmit={submit} className="mt-8 space-y-4"><Field id="full-name" label="Full name" value={form.fullName} onChange={(e) => update('fullName', e.target.value)} required /><Field id="register-email" label="Email address" type="email" value={form.email} onChange={(e) => update('email', e.target.value)} required /><div className="grid gap-4 sm:grid-cols-2"><SelectField id="role" label="I am a" value={form.role} onChange={(e) => update('role', e.target.value)} options={Object.entries(roleLabels).filter(([key]) => key !== 'admin').map(([value, label]) => ({ value, label }))} /><SelectField id="campus" label="Campus" value={form.campus} onChange={(e) => update('campus', e.target.value)} options={campuses.map((value) => ({ value, label: value }))} /></div><SelectField id="department" label="Department" value={form.department} onChange={(e) => update('department', e.target.value)} options={departments.map((value) => ({ value, label: value }))} /><div className="grid gap-4 sm:grid-cols-2"><Field id="graduation-year" label="Graduation year" type="number" placeholder="Optional" value={form.graduationYear} onChange={(e) => update('graduationYear', e.target.value)} /><Field id="register-password" label="Create password" type="password" value={form.password} onChange={(e) => update('password', e.target.value)} minLength={8} required /></div>{error && <p data-testid="status-register-error" className="rounded-lg bg-destructive/10 p-3 text-sm text-destructive">{error}</p>}<Button data-testid="button-submit-register" type="submit" className="mt-3 w-full py-3.5" disabled={register.isPending}>{register.isPending ? <LoaderCircle className="h-4 w-4 animate-spin" /> : <ArrowRight className="h-4 w-4" />}Create my profile</Button></form></AuthLayout>;
}
function Field({ id, label, type = 'text', value, onChange, placeholder, required, minLength }: { id: string; label: string; type?: string; value?: string; onChange?: React.ChangeEventHandler<HTMLInputElement>; placeholder?: string; required?: boolean; minLength?: number }) { return <label className="block"><span className="mb-1.5 block text-xs font-bold text-primary">{label}</span><input data-testid={`input-${id}`} id={id} type={type} autoComplete={type === 'password' ? (id === 'password' ? 'current-password' : 'new-password') : type === 'email' ? 'email' : undefined} value={value} onChange={onChange} placeholder={placeholder} required={required} minLength={minLength} className="w-full rounded-lg border border-input bg-card px-3.5 py-3 text-sm text-primary outline-none placeholder:text-muted-foreground/60 focus:border-accent-foreground focus:ring-2 focus:ring-accent/30" /></label>; }
function SelectField({ id, label, value, onChange, options }: { id: string; label: string; value: string; onChange: React.ChangeEventHandler<HTMLSelectElement>; options: Array<{ value: string; label: string }> }) { return <label className="block"><span className="mb-1.5 block text-xs font-bold text-primary">{label}</span><select data-testid={`select-${id}`} id={id} value={value} onChange={onChange} className="w-full rounded-lg border border-input bg-card px-3.5 py-3 text-sm text-primary outline-none focus:border-accent-foreground focus:ring-2 focus:ring-accent/30">{options.map((option) => <option value={option.value} key={option.value}>{option.label}</option>)}</select></label>; }

function AppShell({ children, user }: { children: React.ReactNode; user?: User | null }) {
  const [open, setOpen] = useState(false);
  const [location] = useLocation();
  const unread = useListNotifications({ query: { queryKey: getListNotificationsQueryKey(), staleTime: 30000 } });
  const unreadCount = unread.data?.filter((n) => !n.read).length ?? 0;
  const visibleNav = NAV.filter((item) => !item.roles || (user && item.roles.includes(user.role)));
  const currentLabel = visibleNav.find((item) => location.startsWith(item.href))?.label ?? 'Profile';

  return <div className="grain min-h-[100dvh] bg-background">
    <aside className={cx('fixed inset-y-0 left-0 z-40 w-64 bg-sidebar px-5 py-6 text-sidebar-foreground transition-transform lg:translate-x-0', open ? 'translate-x-0' : '-translate-x-full')}>
      <div className="flex items-center justify-between">
        <Brand light />
        <button data-testid="button-close-menu" aria-label="Close navigation menu" className="text-sidebar-foreground/60 lg:hidden" onClick={() => setOpen(false)}><X className="h-5 w-5" /></button>
      </div>
      <div className="mt-12">
        <div className="mono mb-3 px-3 text-[9px] font-bold uppercase tracking-[.2em] text-sidebar-foreground/40">{user?.role === 'admin' ? 'Platform operations' : `${roleLabels[user?.role ?? 'student']} workspace`}</div>
        <nav className="space-y-1" aria-label="Primary navigation">
          {visibleNav.map(({ href, label, icon: Icon }) => <Link data-testid={`link-nav-${label.toLowerCase().replaceAll(' ', '-')}`} onClick={() => setOpen(false)} href={href} key={href} aria-current={location === href ? 'page' : undefined} className={cx('flex items-center gap-3 rounded-lg px-3 py-2.5 text-sm font-medium', location === href ? 'bg-sidebar-accent text-sidebar-accent-foreground' : 'text-sidebar-foreground/65 hover:bg-sidebar-accent/60 hover:text-sidebar-foreground')}><Icon className="h-[17px] w-[17px]" />{label}</Link>)}
        </nav>
      </div>
      <div className="absolute bottom-6 left-5 right-5">
        <Link data-testid="link-nav-profile" href="/profile" className="flex items-center gap-3 rounded-lg border border-sidebar-border p-3 hover:bg-sidebar-accent">
          <Avatar user={user} size="sm" />
          <div className="min-w-0"><div className="truncate text-xs font-semibold">{user?.fullName ?? 'Your profile'}</div><div className="truncate text-[10px] text-sidebar-foreground/50">{user ? roleLabels[user.role] : 'Member'}</div></div>
          <Settings2 aria-hidden="true" className="ml-auto h-4 w-4 text-sidebar-foreground/45" />
        </Link>
      </div>
    </aside>
    {open && <button aria-label="Close navigation overlay" className="fixed inset-0 z-30 bg-primary/30 lg:hidden" onClick={() => setOpen(false)} />}
    <div className="lg:pl-64">
      <header className="sticky top-0 z-30 flex h-[72px] items-center justify-between border-b border-border bg-background/90 px-5 backdrop-blur-md sm:px-8">
        <button data-testid="button-open-menu" aria-label="Open navigation menu" className="text-primary lg:hidden" onClick={() => setOpen(true)}><Menu className="h-5 w-5" /></button>
        <div className="hidden items-center gap-2 text-sm text-muted-foreground sm:flex"><span className="h-1.5 w-1.5 rounded-full bg-accent-foreground" /> Amrita Connect <span className="text-border">/</span> <span className="text-primary">{currentLabel}</span></div>
        <div className="flex items-center gap-2">
          <Link data-testid="link-notifications-header" aria-label={`Notifications${unreadCount ? `, ${unreadCount} unread` : ''}`} href="/notifications" className="relative rounded-lg p-2.5 text-muted-foreground hover:bg-muted hover:text-primary"><Bell aria-hidden="true" className="h-[18px] w-[18px]" />{unreadCount > 0 && <span aria-hidden="true" className="absolute right-1.5 top-1.5 h-2 w-2 rounded-full bg-destructive ring-2 ring-background" />}</Link>
          <Link data-testid="link-profile-header" aria-label="Open your profile" href="/profile" className="ml-1"><Avatar user={user} size="sm" /></Link>
        </div>
      </header>
      <main className="mx-auto max-w-7xl px-5 py-8 sm:px-8 lg:py-10">{children}</main>
    </div>
  </div>;
}

function Dashboard() {
  const { data, isLoading, isError, refetch } = useGetDashboardSummary();
  const { data: user } = useGetCurrentUser();
  const copy = dashboardCopy[user?.role ?? 'student'];
  if (isLoading) return <LoadingState rows={4} />;
  if (isError || !data) return <ErrorState onRetry={() => refetch()} />;

  return <>
    <PageTitle eyebrow={`${copy.eyebrow} · ${user?.fullName?.split(' ')[0] ?? 'member'}`} title={copy.title} detail={copy.detail} action={<Link data-testid="link-dashboard-primary-action" href={copy.actionHref} className="inline-flex items-center gap-2 text-sm font-semibold text-primary hover:text-accent-foreground">{copy.action} <ArrowRight className="h-4 w-4" /></Link>} />
    <section className="mb-6 rounded-xl border border-border bg-secondary/50 p-4 sm:p-5">
      <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
        <div><div className="mono text-[9px] font-bold uppercase tracking-[.2em] text-muted-foreground">Role-aware workspace</div><p className="mt-1 text-sm font-semibold text-primary">You are viewing the {roleLabels[user?.role ?? 'student'].toLowerCase()} experience.</p></div>
        <span data-testid="badge-current-role" className="inline-flex w-fit items-center gap-2 rounded-full border border-border bg-card px-3 py-1.5 text-xs font-bold text-primary"><ShieldCheck className="h-3.5 w-3.5 text-accent-foreground" /> {roleLabels[user?.role ?? 'student']} access</span>
      </div>
    </section>
    <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4 animate-rise delay-1"><Metric label="Profile completion" value={`${data.profileCompletion}%`} detail="Make it easier to find you" progress={data.profileCompletion} /><Metric label="People in your network" value={data.peopleCount.toLocaleString()} detail="Across every campus" /><Metric label="Mentorship requests" value={data.mentorshipPending.toString()} detail="Waiting for your reply" accent /><Metric label="Saved opportunities" value={data.savedOpportunities.toString()} detail="Worth revisiting" /></div>
    <div className="mt-8 grid gap-6 xl:grid-cols-[1.2fr_.8fr]"><section className="surface rounded-xl border border-border p-5 sm:p-6"><SectionHeader eyebrow="People to know" title="Recently active" link="/people" /><div className="mt-5 divide-y divide-border">{data.recentPeople?.slice(0, 4).map((person) => <PersonRow key={person.id} user={person} />)}</div>{!data.recentPeople?.length && <EmptyState icon={Users} title="Your network is waiting" detail="Explore the directory to find your first connection." action={<Link href="/people" className="text-sm font-bold text-accent-foreground">Browse people</Link>} />}</section><section className="surface rounded-xl border border-border p-5 sm:p-6"><SectionHeader eyebrow="Next on the calendar" title="Upcoming events" link="/events" /><div className="mt-5 space-y-3">{data.upcoming?.slice(0, 3).map((event) => <EventRow key={event.id} event={event} />)}</div>{!data.upcoming?.length && <EmptyState icon={CalendarDays} title="A quiet calendar" detail="New campus events will show up here." />}</section></div>
    <section className="mt-6 rounded-xl bg-primary p-6 text-primary-foreground sm:p-8"><div className="grid gap-6 md:grid-cols-[1fr_auto] md:items-center"><div><div className="mono text-[10px] uppercase tracking-[.2em] text-primary-foreground/45">A small nudge</div><h2 className="mt-2 text-2xl font-bold tracking-[-.04em]">Your next connection may start with a question.</h2><p className="mt-2 max-w-xl text-sm leading-6 text-primary-foreground/60">Look for someone whose experience meets the edge of your curiosity.</p></div><Link data-testid="link-dashboard-mentorship" href="/mentorship" className="inline-flex items-center justify-center gap-2 rounded-lg bg-accent px-4 py-3 text-sm font-bold text-primary hover:brightness-95">Find a mentor <HeartHandshake className="h-4 w-4" /></Link></div></section>
  </>;
}
function Metric({ label, value, detail, progress, accent }: { label: string; value: string; detail: string; progress?: number; accent?: boolean }) { return <div className={cx('surface rounded-xl border border-border p-5', accent && 'bg-secondary')}><div className="flex items-start justify-between"><span className="text-xs font-semibold text-muted-foreground">{label}</span>{accent && <Sparkles className="h-4 w-4 text-accent-foreground" />}</div><div data-testid={`metric-${label.toLowerCase().replaceAll(' ', '-')}`} className="mt-4 text-3xl font-bold tracking-[-.06em] text-primary">{value}</div>{progress !== undefined ? <div className="mt-3 h-1.5 rounded-full bg-muted"><div className="h-1.5 rounded-full bg-accent-foreground" style={{ width: `${progress}%` }} /></div> : <p className="mt-3 text-xs text-muted-foreground">{detail}</p>} {progress !== undefined && <p className="mt-2 text-xs text-muted-foreground">{detail}</p>}</div>; }
function SectionHeader({ eyebrow, title, link }: { eyebrow: string; title: string; link?: string }) { return <div className="flex items-end justify-between"><div><div className="mono text-[9px] font-bold uppercase tracking-[.18em] text-muted-foreground">{eyebrow}</div><h2 className="mt-1 text-lg font-bold tracking-[-.03em] text-primary">{title}</h2></div>{link && <Link data-testid={`link-section-${title.toLowerCase().replace(' ', '-')}`} href={link} className="text-xs font-bold text-muted-foreground hover:text-primary">View all <ChevronRight className="inline h-3 w-3" /></Link>}</div>; }
function PersonRow({ user }: { user: PublicUser }) { return <Link data-testid={`link-person-${user.id}`} href={`/people/${user.id}`} className="flex items-center gap-3 py-3.5 group"><Avatar user={user} size="sm" /><div className="min-w-0 flex-1"><div className="flex items-center gap-1.5 text-sm font-bold text-primary group-hover:text-accent-foreground">{user.fullName}{user.verified && <Check className="h-3 w-3 text-accent-foreground" />}</div><p className="truncate text-xs text-muted-foreground">{user.headline || `${roleLabels[user.role]} · ${user.department}`}</p></div><span className="hidden text-xs text-muted-foreground sm:block">{user.campus}</span><ChevronRight className="h-4 w-4 text-border group-hover:text-primary" /></Link>; }
function EventRow({ event }: { event: Event }) { return <Link data-testid={`link-event-${event.id}`} href="/events" className="flex gap-3 rounded-lg border border-border p-3 hover:bg-muted"><div className="min-w-11 rounded-md bg-secondary px-2 py-1 text-center"><div className="mono text-[9px] font-bold uppercase text-muted-foreground">{new Date(event.date).toLocaleDateString('en-IN', { month: 'short' })}</div><div className="text-lg font-bold leading-5 text-primary">{new Date(event.date).getDate()}</div></div><div className="min-w-0"><div className="truncate text-sm font-bold text-primary">{event.title}</div><div className="mt-1 truncate text-xs text-muted-foreground">{event.campus} · {event.venue}</div></div></Link>; }

function PeoplePage() {
  const [search, setSearch] = useState(''); const [role, setRole] = useState(''); const [campus, setCampus] = useState(''); const params = useMemo(() => ({ search: search || undefined, role: role ? role as 'student' | 'alumni' | 'faculty' | 'researcher' | 'admin' : undefined, campus: campus || undefined, page: 1, pageSize: 20 }), [search, role, campus]); const { data, isLoading, isError, refetch } = useListUsers(params, { query: { queryKey: getListUsersQueryKey(params) } }); return <><PageTitle eyebrow="Directory" title="People worth knowing." detail="Search the full Amrita community by experience, campus, or discipline." /><div className="mb-6 grid gap-3 md:grid-cols-[1fr_180px_180px]"><label className="relative block"><Search className="absolute left-3.5 top-3 h-4 w-4 text-muted-foreground" /><input data-testid="input-people-search" value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Search names, skills, interests..." className="w-full rounded-lg border border-input bg-card py-2.5 pl-10 pr-3 text-sm outline-none focus:border-accent-foreground" /></label><SelectField id="people-role-filter" label="" value={role} onChange={(e) => setRole(e.target.value)} options={[{ value: '', label: 'All roles' }, ...Object.entries(roleLabels).map(([value, label]) => ({ value, label }))]} /><SelectField id="people-campus-filter" label="" value={campus} onChange={(e) => setCampus(e.target.value)} options={[{ value: '', label: 'All campuses' }, ...campuses.map((value) => ({ value, label: value }))]} /></div>{isLoading ? <LoadingState rows={5} /> : isError ? <ErrorState onRetry={() => refetch()} /> : !data?.items?.length ? <EmptyState icon={Users} title="No people match that search" detail="Try a broader search or remove one of the filters." action={<Button variant="outline" onClick={() => { setSearch(''); setRole(''); setCampus(''); }}>Clear filters</Button>} /> : <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{data.items.map((person, i) => <PersonCard key={person.id} user={person} index={i} />)}</div>}</>;
}
function PersonCard({ user, index = 0 }: { user: PublicUser; index?: number }) { return <Link data-testid={`card-person-${user.id}`} href={`/people/${user.id}`} className={cx('surface group rounded-xl border border-border p-5 animate-rise', `delay-${Math.min(index + 1, 3)}`)}><div className="flex items-start justify-between"><Avatar user={user} /><span className="rounded-md bg-muted px-2 py-1 text-[10px] font-semibold text-muted-foreground">{roleLabels[user.role]}</span></div><div className="mt-4 flex items-center gap-1.5 text-lg font-bold tracking-[-.04em] text-primary group-hover:text-accent-foreground">{user.fullName}{user.verified && <Check className="h-4 w-4 text-accent-foreground" />}</div><p className="mt-1 line-clamp-2 min-h-10 text-sm leading-5 text-muted-foreground">{user.headline || `${user.department} · ${user.campus}`}</p><div className="mt-4 flex items-center gap-2 border-t border-border pt-4 text-xs text-muted-foreground"><span>{user.campus}</span><span className="text-border">·</span><span>{user.department}</span></div>{user.skills?.length > 0 && <div className="mt-3 flex flex-wrap gap-1.5">{user.skills.slice(0, 3).map((skill) => <Tag key={skill}>{skill}</Tag>)}</div>}</Link>; }

function PublicProfilePage() {
  const { id = '' } = useParams<{ id: string }>(); const { data: person, isLoading, isError, refetch } = useGetUser(id); const [showRequest, setShowRequest] = useState(false); if (isLoading) return <LoadingState rows={2} />; if (isError || !person) return <ErrorState onRetry={() => refetch()} />; return <><Link data-testid="link-back-people" href="/people" className="mb-6 inline-flex items-center gap-2 text-sm font-semibold text-muted-foreground hover:text-primary"><ChevronRight className="h-4 w-4 rotate-180" /> Back to people</Link><div className="surface overflow-hidden rounded-xl border border-border"><div className="h-28 bg-primary sm:h-40" /><div className="px-5 pb-7 sm:px-8"><div className="-mt-10 flex flex-col gap-5 sm:-mt-12 sm:flex-row sm:items-end sm:justify-between"><Avatar user={person} size="lg" /><Button data-testid="button-request-mentorship" onClick={() => setShowRequest(true)}><HeartHandshake className="h-4 w-4" />Ask for mentorship</Button></div><div className="mt-5"><div className="flex flex-wrap items-center gap-2"><h1 className="text-3xl font-bold tracking-[-.06em] text-primary">{person.fullName}</h1>{person.verified && <Check className="h-5 w-5 text-accent-foreground" />}</div><p className="mt-1 text-base text-muted-foreground">{person.headline}</p><div className="mt-3 flex flex-wrap gap-x-4 gap-y-1 text-xs text-muted-foreground"><span>{roleLabels[person.role]}</span><span>{person.campus}</span><span>{person.department}</span>{person.company && <span>{person.company}{person.jobRole && ` · ${person.jobRole}`}</span>}</div></div><div className="mt-8 grid gap-8 border-t border-border pt-7 lg:grid-cols-[1fr_280px]"><div><h2 className="font-bold text-primary">About</h2><p className="mt-3 whitespace-pre-line text-sm leading-7 text-muted-foreground">{person.bio || 'This member has not added a bio yet.'}</p><InfoGroup title="Skills" items={person.skills} /><InfoGroup title="Interested in" items={person.interests} /></div><div className="space-y-5"><ProfileAside title="Can help with" items={person.helpWith} /><ProfileAside title="Looking for" items={person.lookingFor} /></div></div></div></div>{showRequest && <MentorshipDialog mentor={person} onClose={() => setShowRequest(false)} />}</>; }
function InfoGroup({ title, items = [] }: { title: string; items?: string[] }) { return items?.length ? <div className="mt-8"><h3 className="text-xs font-bold uppercase tracking-[.14em] text-muted-foreground">{title}</h3><div className="mt-3 flex flex-wrap gap-2">{items.map((item) => <Tag key={item} warm>{item}</Tag>)}</div></div> : null; }
function ProfileAside({ title, items = [] }: { title: string; items?: string[] }) { return <div><h3 className="text-xs font-bold uppercase tracking-[.14em] text-muted-foreground">{title}</h3><div className="mt-3 space-y-2">{items?.length ? items.map((item) => <div className="flex gap-2 text-sm text-primary" key={item}><span className="mt-2 h-1.5 w-1.5 shrink-0 rounded-full bg-accent-foreground" />{item}</div>) : <span className="text-sm text-muted-foreground">Not shared yet</span>}</div></div>; }
function MentorshipDialog({ mentor, onClose }: { mentor: PublicUser; onClose: () => void }) { const create = useCreateMentorshipRequest(); const [form, setForm] = useState({ topic: '', reason: '', message: '' }); const queryClient = useQueryClient(); const submit = (e: React.FormEvent) => { e.preventDefault(); create.mutate({ data: { mentorId: mentor.id, ...form } }, { onSuccess: () => { queryClient.invalidateQueries({ queryKey: getListMentorshipRequestsQueryKey() }); onClose(); } }); }; return <div className="fixed inset-0 z-50 grid place-items-center bg-primary/35 p-4 backdrop-blur-sm"><div className="w-full max-w-lg rounded-xl border border-border bg-card p-6 shadow-xl"><div className="flex items-start justify-between"><div><div className="mono text-[10px] uppercase tracking-[.18em] text-muted-foreground">A thoughtful ask</div><h2 className="mt-1 text-2xl font-bold tracking-[-.04em] text-primary">Ask {mentor.fullName.split(' ')[0]} to mentor you</h2></div><button data-testid="button-close-mentorship-dialog" onClick={onClose} className="rounded-lg p-2 text-muted-foreground hover:bg-muted"><X className="h-4 w-4" /></button></div><form onSubmit={submit} className="mt-6 space-y-4"><Field id="mentorship-topic" label="What would you like to learn?" value={form.topic} onChange={(e) => setForm({ ...form, topic: e.target.value })} required /><Field id="mentorship-reason" label="Why this person?" value={form.reason} onChange={(e) => setForm({ ...form, reason: e.target.value })} required /><label className="block"><span className="mb-1.5 block text-xs font-bold text-primary">Your note</span><textarea data-testid="textarea-mentorship-message" value={form.message} onChange={(e) => setForm({ ...form, message: e.target.value })} required rows={4} className="w-full rounded-lg border border-input bg-card px-3.5 py-3 text-sm outline-none focus:border-accent-foreground" placeholder="Introduce yourself and share what a useful first conversation looks like." /></label><div className="flex justify-end gap-2 pt-2"><Button type="button" variant="quiet" onClick={onClose}>Cancel</Button><Button data-testid="button-submit-mentorship" type="submit" disabled={create.isPending}>{create.isPending ? <LoaderCircle className="h-4 w-4 animate-spin" /> : <Send className="h-4 w-4" />}Send request</Button></div></form></div></div>; }

function MentorshipPage() {
  const { data, isLoading, isError, refetch } = useListMentorshipRequests(); const status = useUpdateMentorshipRequestStatus(); const queryClient = useQueryClient(); const [filter, setFilter] = useState('all'); const items = data?.filter((item) => filter === 'all' || item.status === filter) ?? []; const update = (id: string, value: 'accepted' | 'rejected') => status.mutate({ id, data: { status: value } }, { onSuccess: () => queryClient.invalidateQueries({ queryKey: getListMentorshipRequestsQueryKey() }) }); return <><PageTitle eyebrow="Mentorship" title="Make room for guidance." detail="Keep track of the conversations you have started and the ones waiting on you." action={<div className="flex rounded-lg border border-border bg-card p-1">{['all', 'pending', 'accepted'].map((value) => <button data-testid={`button-filter-mentorship-${value}`} key={value} onClick={() => setFilter(value)} className={cx('rounded-md px-3 py-1.5 text-xs font-bold capitalize', filter === value ? 'bg-primary text-primary-foreground' : 'text-muted-foreground')}>{value}</button>)}</div>} />{isLoading ? <LoadingState rows={3} /> : isError ? <ErrorState onRetry={() => refetch()} /> : !items.length ? <EmptyState icon={HeartHandshake} title={filter === 'all' ? 'No mentorship requests yet' : `No ${filter} requests`} detail="When you find the right person, a clear and considered note is a good place to start." action={<Link href="/people" className="text-sm font-bold text-accent-foreground">Explore the directory</Link>} /> : <div className="space-y-4">{items.map((item) => <MentorshipCard key={item.id} item={item} onUpdate={update} pending={status.isPending} />)}</div>}</>; }
function MentorshipCard({ item, onUpdate, pending }: { item: MentorshipRequest; onUpdate: (id: string, status: 'accepted' | 'rejected') => void; pending: boolean }) { return <div className="surface rounded-xl border border-border p-5 sm:p-6"><div className="flex flex-col gap-5 sm:flex-row sm:items-start"><Avatar user={item.requester} /><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><h2 className="font-bold text-primary">{item.requester.fullName}</h2><Status status={item.status} /></div><p className="mt-1 text-xs text-muted-foreground">Requesting mentorship · {relative(item.createdAt)}</p><p className="mt-4 text-sm leading-6 text-primary">{item.message}</p><div className="mt-4 flex flex-wrap gap-2"><Tag warm>{item.topic}</Tag><Tag>{item.reason}</Tag></div></div>{item.status === 'pending' && <div className="flex shrink-0 gap-2 sm:flex-col"><Button data-testid={`button-accept-mentorship-${item.id}`} className="px-3 py-2" disabled={pending} onClick={() => onUpdate(item.id, 'accepted')}><Check className="h-4 w-4" />Accept</Button><Button data-testid={`button-reject-mentorship-${item.id}`} variant="quiet" className="px-3 py-2" disabled={pending} onClick={() => onUpdate(item.id, 'rejected')}>Decline</Button></div>}</div></div>; }
function Status({ status }: { status: string }) { return <span data-testid={`status-${status}`} className={cx('rounded-full px-2.5 py-1 text-[10px] font-bold capitalize', status === 'accepted' ? 'bg-emerald-100 text-emerald-800' : status === 'rejected' ? 'bg-destructive/10 text-destructive' : 'bg-accent/40 text-primary')}>{status}</span>; }

function CollaborationsPage() {
  const [search, setSearch] = useState(''); const [showCreate, setShowCreate] = useState(false); const params = useMemo(() => ({ search: search || undefined, page: 1, pageSize: 20 }), [search]); const { data, isLoading, isError, refetch } = useListCollaborations(params, { query: { queryKey: getListCollaborationsQueryKey(params) } }); return <><PageTitle eyebrow="Collaborate" title="Build something together." detail="Find open questions and bring the right mix of people around them." action={<Button data-testid="button-create-collaboration" onClick={() => setShowCreate(true)}><Zap className="h-4 w-4" />Post a project</Button>} /><label className="relative mb-6 block max-w-xl"><Search className="absolute left-3.5 top-3 h-4 w-4 text-muted-foreground" /><input data-testid="input-collaborations-search" value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Search projects, skills, or categories..." className="w-full rounded-lg border border-input bg-card py-2.5 pl-10 text-sm outline-none focus:border-accent-foreground" /></label>{isLoading ? <LoadingState rows={4} /> : isError ? <ErrorState onRetry={() => refetch()} /> : !data?.items?.length ? <EmptyState icon={Network} title="No projects posted yet" detail="Have an idea that needs a team? Give it a shape and invite the community in." action={<Button onClick={() => setShowCreate(true)}>Post the first project</Button>} /> : <div className="grid gap-4 lg:grid-cols-2">{data.items.map((item) => <CollaborationCard key={item.id} item={item} />)}</div>}{showCreate && <CreateCollaborationDialog onClose={() => setShowCreate(false)} />}</>; }
function CollaborationCard({ item }: { item: Collaboration }) { return <div className="surface rounded-xl border border-border p-5 sm:p-6"><div className="flex items-start justify-between gap-4"><Tag warm>{item.category}</Tag><span className="mono text-[10px] text-muted-foreground">Due {formatDate(item.deadline)}</span></div><h2 className="mt-4 text-xl font-bold tracking-[-.04em] text-primary">{item.title}</h2><p className="mt-2 line-clamp-3 text-sm leading-6 text-muted-foreground">{item.description}</p><div className="mt-5 flex flex-wrap gap-1.5">{item.requiredSkills?.map((skill) => <Tag key={skill}>{skill}</Tag>)}</div><div className="mt-6 flex items-center justify-between border-t border-border pt-4"><div className="flex items-center gap-2"><Avatar user={item.creator} size="sm" /><div><p className="text-xs font-bold text-primary">{item.creator.fullName}</p><p className="text-[10px] text-muted-foreground">{item.memberCount} of {item.teamSize} spots filled</p></div></div><Button variant="outline" className="px-3 py-2" onClick={() => undefined}>View project <ArrowRight className="h-3.5 w-3.5" /></Button></div></div>; }
function CreateCollaborationDialog({ onClose }: { onClose: () => void }) { const create = useCreateCollaboration(); const queryClient = useQueryClient(); const [form, setForm] = useState({ title: '', description: '', requiredSkills: '', teamSize: '3', deadline: '', category: 'Research' }); const set = (key: string, value: string) => setForm((prev) => ({ ...prev, [key]: value })); const submit = (e: React.FormEvent) => { e.preventDefault(); create.mutate({ data: { ...form, requiredSkills: form.requiredSkills.split(',').map((x) => x.trim()).filter(Boolean), teamSize: Number(form.teamSize) } }, { onSuccess: () => { queryClient.invalidateQueries({ queryKey: getListCollaborationsQueryKey() }); onClose(); } }); }; return <div className="fixed inset-0 z-50 grid place-items-center bg-primary/35 p-4 backdrop-blur-sm"><div className="max-h-[90vh] w-full max-w-lg overflow-y-auto rounded-xl border border-border bg-card p-6 shadow-xl"><div className="flex items-start justify-between"><div><div className="mono text-[10px] uppercase tracking-[.18em] text-muted-foreground">Open call</div><h2 className="mt-1 text-2xl font-bold tracking-[-.04em] text-primary">Post a project</h2></div><button data-testid="button-close-collaboration-dialog" onClick={onClose} className="rounded-lg p-2 text-muted-foreground hover:bg-muted"><X className="h-4 w-4" /></button></div><form onSubmit={submit} className="mt-6 space-y-4"><Field id="collaboration-title" label="Project title" value={form.title} onChange={(e) => set('title', e.target.value)} required /><label className="block"><span className="mb-1.5 block text-xs font-bold text-primary">What are you working on?</span><textarea data-testid="textarea-collaboration-description" value={form.description} onChange={(e) => set('description', e.target.value)} required rows={4} className="w-full rounded-lg border border-input bg-card px-3.5 py-3 text-sm outline-none focus:border-accent-foreground" /></label><div className="grid gap-4 sm:grid-cols-2"><Field id="collaboration-skills" label="Skills needed" placeholder="Python, design, fieldwork" value={form.requiredSkills} onChange={(e) => set('requiredSkills', e.target.value)} required /><Field id="collaboration-deadline" label="Deadline" type="date" value={form.deadline} onChange={(e) => set('deadline', e.target.value)} required /></div><div className="grid gap-4 sm:grid-cols-2"><SelectField id="collaboration-category" label="Category" value={form.category} onChange={(e) => set('category', e.target.value)} options={['Research', 'Startup', 'Student life', 'Community'].map((value) => ({ value, label: value }))} /><Field id="collaboration-team-size" label="Team size" type="number" value={form.teamSize} onChange={(e) => set('teamSize', e.target.value)} required /></div><div className="flex justify-end gap-2 pt-2"><Button type="button" variant="quiet" onClick={onClose}>Cancel</Button><Button data-testid="button-submit-collaboration" type="submit" disabled={create.isPending}>{create.isPending ? <LoaderCircle className="h-4 w-4 animate-spin" /> : <Send className="h-4 w-4" />}Publish project</Button></div></form></div></div>; }

function OpportunitiesPage() {
  const [search, setSearch] = useState('');
  const [actionError, setActionError] = useState<string | null>(null);
  const params = useMemo(() => ({ search: search || undefined, page: 1, pageSize: 20 }), [search]);
  const queryClient = useQueryClient();
  const save = useSaveOpportunity();
  const unsave = useUnsaveOpportunity();
  const { data, isLoading, isError, refetch } = useListOpportunities(params, { query: { queryKey: getListOpportunitiesQueryKey(params) } });
  const items = data?.items ?? [];
  const saving = save.isPending || unsave.isPending;
  const toggleSave = (item: Opportunity) => {
    setActionError(null);
    const mutation = item.saved ? unsave : save;
    mutation.mutate({ id: item.id }, {
      onSuccess: () => {
        queryClient.invalidateQueries({ queryKey: getListOpportunitiesQueryKey() });
        queryClient.invalidateQueries({ queryKey: getGetDashboardSummaryQueryKey() });
      },
      onError: () => setActionError('That save could not be updated. Please try again.'),
    });
  };
  return <><PageTitle eyebrow="Opportunities" title="A next step, if it fits." detail="Fellowships, roles, research calls, and chances to turn your interests into momentum." /><label className="relative mb-6 block max-w-xl"><Search className="absolute left-3.5 top-3 h-4 w-4 text-muted-foreground" /><input data-testid="input-opportunities-search" value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Search opportunities..." className="w-full rounded-lg border border-input bg-card py-2.5 pl-10 text-sm outline-none focus:border-accent-foreground" /></label>{actionError && <p role="alert" className="mb-4 text-sm font-semibold text-destructive">{actionError}</p>}{isLoading ? <LoadingState rows={4} /> : isError ? <ErrorState onRetry={() => refetch()} /> : !items.length ? <EmptyState icon={BriefcaseBusiness} title="No opportunities found" detail="Try a different phrase. New calls are added throughout the year." /> : <div className="space-y-3">{items.map((item) => <OpportunityRow key={item.id} item={item} onSave={() => toggleSave(item)} saving={saving} />)}</div>}</>;
}
function OpportunityRow({ item, onSave, saving }: { item: Opportunity; onSave: () => void; saving: boolean }) { return <div className="surface flex flex-col gap-5 rounded-xl border border-border p-5 sm:flex-row sm:items-start sm:p-6"><div className="grid h-11 w-11 shrink-0 place-items-center rounded-lg bg-secondary text-primary"><BriefcaseBusiness className="h-5 w-5" /></div><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><Tag warm>{item.category}</Tag><span className="text-xs text-muted-foreground">{item.organization}</span></div><h2 className="mt-2 text-lg font-bold tracking-[-.03em] text-primary">{item.title}</h2><p className="mt-1 max-w-3xl text-sm leading-6 text-muted-foreground">{item.description}</p><div className="mt-4 flex flex-wrap gap-1.5">{item.requiredSkills?.slice(0, 4).map((skill) => <Tag key={skill}>{skill}</Tag>)}</div><div className="mt-4 flex flex-wrap gap-x-4 gap-y-1 text-xs text-muted-foreground"><span>Eligibility: {item.eligibility}</span><span>Deadline: <strong className="text-primary">{formatDate(item.deadline, true)}</strong></span></div></div><div className="flex shrink-0 gap-2 sm:flex-col"><button aria-label={item.saved ? `Remove ${item.title} from saved opportunities` : `Save ${item.title}`} data-testid={`button-save-opportunity-${item.id}`} onClick={onSave} disabled={saving} className={cx('rounded-lg border p-2.5', item.saved ? 'border-accent bg-accent/30 text-primary' : 'border-border text-muted-foreground hover:text-primary')}>{item.saved ? <Check className="h-4 w-4" /> : <HeartHandshake className="h-4 w-4" />}</button><a data-testid={`link-apply-opportunity-${item.id}`} href={item.applicationUrl} target="_blank" rel="noreferrer" className="inline-flex items-center justify-center gap-2 rounded-lg bg-primary px-3 py-2.5 text-xs font-bold text-primary-foreground hover:opacity-90">Apply <ArrowRight className="h-3.5 w-3.5" /></a></div></div>; }

function EventsPage() {
  const [campus, setCampus] = useState('');
  const [actionError, setActionError] = useState<string | null>(null);
  const params = useMemo(() => ({ campus: campus || undefined, page: 1, pageSize: 20 }), [campus]);
  const queryClient = useQueryClient();
  const register = useRegisterForEvent();
  const unregister = useUnregisterFromEvent();
  const { data, isLoading, isError, refetch } = useListEvents(params, { query: { queryKey: getListEventsQueryKey(params) } });
  const items = data?.items ?? [];
  const registering = register.isPending || unregister.isPending;
  const toggleRegistration = (event: Event) => {
    setActionError(null);
    const mutation = event.registered ? unregister : register;
    mutation.mutate({ id: event.id }, {
      onSuccess: () => {
        queryClient.invalidateQueries({ queryKey: getListEventsQueryKey() });
        queryClient.invalidateQueries({ queryKey: getGetDashboardSummaryQueryKey() });
      },
      onError: () => setActionError('That registration could not be updated. The event may be full.'),
    });
  };
  return <><PageTitle eyebrow="Events" title="Show up for something." detail="Talks, workshops, reunions, and the small moments that make a campus feel connected." action={<SelectField id="events-campus-filter" label="" value={campus} onChange={(e) => setCampus(e.target.value)} options={[{ value: '', label: 'All campuses' }, ...campuses.map((value) => ({ value, label: value }))]} />} />{actionError && <p role="alert" className="mb-4 text-sm font-semibold text-destructive">{actionError}</p>}{isLoading ? <LoadingState rows={4} /> : isError ? <ErrorState onRetry={() => refetch()} /> : !items.length ? <EmptyState icon={CalendarDays} title="Nothing on the calendar yet" detail="Check back soon for the next set of gatherings." /> : <div className="grid gap-4 md:grid-cols-2">{items.map((event) => <EventCard key={event.id} event={event} registered={event.registered} onRegister={() => toggleRegistration(event)} registering={registering} />)}</div>}</>;
}
function EventCard({ event, registered, onRegister, registering }: { event: Event; registered: boolean; onRegister: () => void; registering: boolean }) { return <div className="surface rounded-xl border border-border p-5 sm:p-6"><div className="flex gap-4"><div className="w-14 shrink-0 rounded-lg bg-primary p-2 text-center text-primary-foreground"><div className="mono text-[9px] uppercase tracking-wider text-accent">{new Date(event.date).toLocaleDateString('en-IN', { month: 'short' })}</div><div className="text-2xl font-bold">{new Date(event.date).getDate()}</div><div className="text-[9px] uppercase text-primary-foreground/50">{new Date(event.date).toLocaleDateString('en-IN', { weekday: 'short' })}</div></div><div className="min-w-0"><h2 className="text-lg font-bold tracking-[-.03em] text-primary">{event.title}</h2><p className="mt-1 text-xs text-muted-foreground">{event.campus} · {event.venue}</p></div></div><p className="mt-5 line-clamp-3 text-sm leading-6 text-muted-foreground">{event.description}</p><div className="mt-5 flex items-center justify-between border-t border-border pt-4"><span className="text-xs text-muted-foreground">By {event.organizer}</span><Button aria-label={registered ? `Cancel registration for ${event.title}` : `Register for ${event.title}`} data-testid={`button-register-event-${event.id}`} variant={registered ? 'quiet' : 'outline'} className="px-3 py-2" disabled={registering} onClick={onRegister}>{registered ? <><Check className="h-3.5 w-3.5" />Registered</> : 'Register'}</Button></div></div>; }

function NotificationsPage() {
  const { data, isLoading, isError, refetch } = useListNotifications(); const mark = useMarkNotificationRead(); const queryClient = useQueryClient(); const items = data ?? []; const read = (notification: Notification) => { if (!notification.read) mark.mutate({ id: notification.id }, { onSuccess: () => queryClient.invalidateQueries({ queryKey: getListNotificationsQueryKey() }) }); }; return <><PageTitle eyebrow="Notifications" title="Keep in the loop." detail="A quiet inbox for the things that need your attention." action={<Link data-testid="link-notifications-people" href="/people" className="text-sm font-semibold text-primary">Find people <ArrowRight className="inline h-4 w-4" /></Link>} />{isLoading ? <LoadingState rows={4} /> : isError ? <ErrorState onRetry={() => refetch()} /> : !items.length ? <EmptyState icon={Bell} title="You are all caught up" detail="New requests, invitations, and updates will land here." /> : <div className="max-w-3xl divide-y divide-border rounded-xl border border-border bg-card">{items.map((item) => <button data-testid={`button-notification-${item.id}`} onClick={() => read(item)} key={item.id} className={cx('flex w-full gap-4 p-5 text-left hover:bg-muted', !item.read && 'bg-secondary/40')}><div className={cx('mt-1 h-2 w-2 shrink-0 rounded-full', item.read ? 'bg-border' : 'bg-accent-foreground')} /><div className="min-w-0 flex-1"><div className="flex justify-between gap-4"><h2 className="text-sm font-bold text-primary">{item.title}</h2><span className="shrink-0 text-[10px] text-muted-foreground">{relative(item.createdAt)}</span></div><p className="mt-1 text-sm leading-6 text-muted-foreground">{item.message}</p></div></button>)}</div>}</>;
}

function ProfilePage() {
  const { data: user, isLoading, isError, refetch } = useGetCurrentUser();
  const update = useUpdateMyProfile();
  const [saved, setSaved] = useState(false);
  const [form, setForm] = useState<Partial<User> | null>(null);
  if (isLoading) return <LoadingState rows={3} />;
  if (isError || !user) return <ErrorState onRetry={() => refetch()} />;
  const values = form ?? user;
  const set = (key: string, value: string) => setForm((prev) => ({ ...(prev ?? user), [key]: value }));
  const setList = (key: string, value: string) => setForm((prev) => ({ ...(prev ?? user), [key]: value.split(',').map((item) => item.trim()).filter(Boolean) }));
  const submit = (e: React.FormEvent) => {
    e.preventDefault();
    update.mutate({ data: { headline: values.headline, bio: values.bio, company: values.company, jobRole: values.jobRole, skills: values.skills, interests: values.interests, helpWith: values.helpWith, lookingFor: values.lookingFor, avatarUrl: values.avatarUrl } }, { onSuccess: () => { setSaved(true); setTimeout(() => setSaved(false), 2400); } });
  };
  return <><PageTitle eyebrow="Your profile" title="Make it easy to find you." detail="A little context turns a directory listing into a useful invitation." action={saved ? <span className="inline-flex items-center gap-2 text-sm font-bold text-emerald-700"><Check className="h-4 w-4" />Changes saved</span> : undefined} /><form onSubmit={submit} className="grid gap-6 lg:grid-cols-[.8fr_1.2fr]">
    <div className="surface h-fit rounded-xl border border-border p-6"><div className="flex items-center gap-4"><Avatar user={values} size="lg" /><div><h2 className="font-bold text-primary">{user.fullName}</h2><p className="mt-1 text-xs text-muted-foreground">{roleLabels[user.role]} · {user.campus}</p><p className="mt-2 text-[11px] text-muted-foreground">Your identity details are managed by Amrita.</p></div></div><div className="mt-7 border-t border-border pt-5"><div className="flex justify-between text-xs"><span className="font-semibold text-muted-foreground">Profile strength</span><span className="font-bold text-primary">Active</span></div><div className="mt-2 h-1.5 rounded-full bg-muted"><div className="h-1.5 w-3/4 rounded-full bg-accent-foreground" /></div></div></div>
    <div className="surface rounded-xl border border-border p-6 sm:p-8"><h2 className="text-lg font-bold text-primary">What should people know?</h2><p className="mt-1 text-sm text-muted-foreground">Keep it specific. Your profile is your first hello.</p><div className="mt-6 space-y-5"><Field id="profile-headline" label="Headline" value={values.headline ?? ''} onChange={(e) => set('headline', e.target.value)} placeholder="What are you working on right now?" /><label className="block"><span className="mb-1.5 block text-xs font-bold text-primary">About you</span><textarea data-testid="textarea-profile-bio" value={values.bio ?? ''} onChange={(e) => set('bio', e.target.value)} rows={5} className="w-full rounded-lg border border-input bg-card px-3.5 py-3 text-sm outline-none focus:border-accent-foreground" placeholder="A short, human introduction..." /></label><div className="grid gap-4 sm:grid-cols-2"><Field id="profile-company" label="Company / lab" value={values.company ?? ''} onChange={(e) => set('company', e.target.value)} /><Field id="profile-job-role" label="Role / title" value={values.jobRole ?? ''} onChange={(e) => set('jobRole', e.target.value)} /></div><Field id="profile-skills" label="Skills" value={values.skills?.join(', ') ?? ''} onChange={(e) => setList('skills', e.target.value)} placeholder="Separate skills with commas" /><Field id="profile-interests" label="Interests" value={values.interests?.join(', ') ?? ''} onChange={(e) => setList('interests', e.target.value)} /><div className="grid gap-4 sm:grid-cols-2"><Field id="profile-help-with" label="I can help with" value={values.helpWith?.join(', ') ?? ''} onChange={(e) => setList('helpWith', e.target.value)} /><Field id="profile-looking-for" label="I am looking for" value={values.lookingFor?.join(', ') ?? ''} onChange={(e) => setList('lookingFor', e.target.value)} /></div><div className="flex justify-end pt-2"><Button data-testid="button-save-profile" type="submit" disabled={update.isPending}>{update.isPending ? <LoaderCircle className="h-4 w-4 animate-spin" /> : <Check className="h-4 w-4" />}Save profile</Button></div></div></div>
  </form></>;
}

function AdminPage() {
  const { data: user, isLoading: userLoading } = useGetCurrentUser();
  const { data, isLoading, isError, refetch } = useGetAdminSummary({ query: { queryKey: getGetAdminSummaryQueryKey(), enabled: user?.role === 'admin' } });
  if (userLoading || isLoading) return <LoadingState rows={4} />;
  if (!user || user.role !== 'admin') return <EmptyState icon={ShieldCheck} title="This workspace is restricted" detail="Admin console access is limited to platform administrators." action={<Link href="/dashboard" className="text-sm font-bold text-accent-foreground">Return to your dashboard</Link>} />;
  if (isError || !data) return <ErrorState onRetry={() => refetch()} />;

  return <>
    <PageTitle eyebrow="Platform operations" title="Keep the commons healthy." detail="A focused view of the people and activity shaping Amrita Connect." />
    <section className="mb-6 rounded-xl border border-primary/15 bg-primary p-5 text-primary-foreground sm:p-6">
      <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
        <div><div className="mono text-[9px] font-bold uppercase tracking-[.2em] text-primary-foreground/50">Administrator access</div><h2 className="mt-2 text-xl font-bold tracking-[-.03em]">A calm control room for a trusted network.</h2><p className="mt-2 max-w-2xl text-sm leading-6 text-primary-foreground/65">Review the network at a glance before moving into verification, reports, and community operations.</p></div>
        <div className="grid h-12 w-12 shrink-0 place-items-center rounded-xl bg-accent text-primary"><BarChart3 className="h-5 w-5" /></div>
      </div>
    </section>
    <div data-testid="admin-summary-grid" className="grid gap-4 sm:grid-cols-3">
      <Metric label="Members" value={data.users.toLocaleString()} detail="Across every campus" />
      <Metric label="Opportunities" value={data.opportunities.toLocaleString()} detail="Published opportunities" accent />
      <Metric label="Events" value={data.events.toLocaleString()} detail="On the shared calendar" />
    </div>
    <div className="mt-8 grid gap-6 lg:grid-cols-2">
      <section className="surface rounded-xl border border-border p-5 sm:p-6"><SectionHeader eyebrow="Next operational views" title="Keep building the trust layer" /><div className="mt-5 space-y-3">{[['Verification queue', 'Review official identity signals and keep member badges meaningful.'], ['Reports & moderation', 'Give members a clear, accountable path to report concerns.'], ['Engagement analytics', 'Understand which campuses, roles, and pathways are finding value.']].map(([title, detail]) => <div key={title} className="flex gap-3 rounded-lg border border-border bg-card p-4"><div className="mt-0.5 grid h-8 w-8 shrink-0 place-items-center rounded-lg bg-secondary text-accent-foreground"><ShieldCheck className="h-4 w-4" /></div><div><h3 className="text-sm font-bold text-primary">{title}</h3><p className="mt-1 text-xs leading-5 text-muted-foreground">{detail}</p></div></div>)}</div></section>
      <section className="surface rounded-xl border border-border p-5 sm:p-6"><SectionHeader eyebrow="Quick access" title="Review the public network" /><div className="mt-5 grid gap-3 sm:grid-cols-3 lg:grid-cols-1">{[['People', '/people', Users], ['Opportunities', '/opportunities', BriefcaseBusiness], ['Events', '/events', CalendarDays]].map(([label, href, Icon]) => <Link key={label as string} href={href as string} className="flex items-center gap-3 rounded-lg border border-border bg-card p-4 transition-colors hover:bg-muted"><span className="grid h-8 w-8 place-items-center rounded-lg bg-secondary text-primary"><Icon className="h-4 w-4" /></span><span className="text-sm font-bold text-primary">{label as string}</span><ArrowRight className="ml-auto h-4 w-4 text-muted-foreground" /></Link>)}</div></section>
    </div>
  </>;
}

function NotFound() { return <div className="grid min-h-[100dvh] place-items-center bg-background p-6 text-center"><div><div className="mono text-[10px] uppercase tracking-[.2em] text-muted-foreground">404 / Off the map</div><h1 className="mt-4 text-5xl font-bold tracking-[-.06em] text-primary">This path is not connected.</h1><Link href="/" className="mt-6 inline-flex items-center gap-2 text-sm font-bold text-accent-foreground">Return home <ArrowRight className="h-4 w-4" /></Link></div></div>; }

function ProtectedRoute({ children }: { children: React.ReactNode }) { const { data: user, isLoading } = useGetCurrentUser(); const [, setLocation] = useLocation(); if (isLoading) return <AppShell><LoadingState rows={4} /></AppShell>; if (!user) { setLocation('/login'); return null; } return <AppShell user={user}>{children}</AppShell>; }
function RoutedErrorBoundary({ children }: { children: React.ReactNode }) { const [location] = useLocation(); return <ErrorBoundary resetKey={location}>{children}</ErrorBoundary>; }
function Router() { return <RoutedErrorBoundary><Switch><Route path="/" component={Landing} /><Route path="/login" component={LoginPage} /><Route path="/register" component={RegisterPage} /><Route path="/dashboard"><ProtectedRoute><Dashboard /></ProtectedRoute></Route><Route path="/admin"><ProtectedRoute><AdminPage /></ProtectedRoute></Route><Route path="/profile"><ProtectedRoute><ProfilePage /></ProtectedRoute></Route><Route path="/people"><ProtectedRoute><PeoplePage /></ProtectedRoute></Route><Route path="/people/:id"><ProtectedRoute><PublicProfilePage /></ProtectedRoute></Route><Route path="/mentorship"><ProtectedRoute><MentorshipPage /></ProtectedRoute></Route><Route path="/collaborations"><ProtectedRoute><CollaborationsPage /></ProtectedRoute></Route><Route path="/opportunities"><ProtectedRoute><OpportunitiesPage /></ProtectedRoute></Route><Route path="/events"><ProtectedRoute><EventsPage /></ProtectedRoute></Route><Route path="/notifications"><ProtectedRoute><NotificationsPage /></ProtectedRoute></Route><Route component={NotFound} /></Switch></RoutedErrorBoundary>; }
function App() { return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><Router /></WouterRouter><Toaster /></TooltipProvider></QueryClientProvider>; }
export default App;
